import json,sys,collections
sys.path.insert(0,'scripts')
from cost_model import CostModel, align, HEADS, HIDDEN
cm=CostModel(64)
def load(fn): return {r['request_id']:r for r in map(json.loads,open(fn))}
def make(rs,key):
    groups=collections.defaultdict(list)
    for r in rs.values(): groups[key(r)].append(r['request_id'])
    S=max(align(r['prompt_len'],64) for r in rs.values())
    recs=[]
    for bi,ids in enumerate(groups.values()):
        for rid in ids:
            recs.append({'request_id':rid,'batch_id':f'b-{bi:06d}','shape':{'seq_align':S,'heads_align':HEADS,'hidden_align':HIDDEN}})
    return recs
for fn in ['input_data/requests_bucket_1.jsonl','input_data/requests_bucket_2.jsonl']:
    rs=load(fn); print(fn)
    for name,key in [('single',lambda r:(r['request_id'],)),('exact_SG',lambda r:(align(r['prompt_len'],64),r['gen_len'])),('exact_G',lambda r:(r['gen_len'],))]:
        plan=make(rs,key); m=cm.plan_metrics(rs,plan)
        print(name,len(set(p['batch_id'] for p in plan)),{k:m[k] for k in ['cost','pad_ratio','p95_latency_ms','sequential_timecost']})
PY
